LC369:
    db `are you sure you want to\nquit this great game?`, 0
    align 8, db 0
LC370:
    db `you want to quit?\nthen, thou hast lost an eighth!`, 0
    align 8, db 0
LC371:
    db `don't go now, there's a \ndimensional shambler waiting\nat the dos prompt!`, 0
    align 8, db 0
LC372:
    db `get outta here and go back\nto your boring programs.`, 0
    align 8, db 0
LC373:
    db `if i were your boss, i'd \n deathmatch ya in a minute!`, 0
    align 8, db 0
LC374:
    db `look, bud. you leave now\nand you forfeit your body count!`, 0
    align 8, db 0
LC375:
    db `just leave. when you come\nback, i'll be waiting with a bat.`, 0
    align 8, db 0
LC376:
    db `you're lucky i don't smack\nyou for thinking about leaving.`, 0
    section .data
    align 32, db 0
doom2_endmsg:
    dq LC369
    dq LC370
    dq LC371
    dq LC372
    dq LC373
    dq LC374
    dq LC375
    dq LC376
    global doom1_endmsg
    section .rodata
    align 8, db 0
LC377:
    db `please don't leave, there's more\ndemons to toast!`, 0
    align 8, db 0
LC378:
    db `let's beat it -- this is turning\ninto a bloodbath!`, 0
    align 8, db 0
LC379:
    db `i wouldn't leave if i were you.\ndos is much worse.`, 0
    align 8, db 0
LC380:
    db `you're trying to say you like dos\nbetter than me, right?`, 0
    align 8, db 0
LC381:
    db `don't leave yet -- there's a\ndemon around that corner!`, 0
    align 8, db 0
LC382:
    db `ya know, next time you come in here\ni'm gonna toast ya.`, 0
    align 8, db 0
LC383:
    db `go ahead and leave. see if i care.`, 0
